  hexToBytes: vi.fn((hex: string) => new Uint8Array(hex.length / 2)),
}));

vi.mock('@cipherbox/sdk-core', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@cipherbox/sdk-core')>();
