1	/**
2	 * moveItem descendant enumeration (D-12) — depth-2+ walk regression.
3	 *
4	 * Guards the zeroization ORDER inside enumerateMoveDescendants: a non-root
5	 * node's readKey is the AAD-bearing parent key for its own children, so it
6	 * must stay intact through the children loop and be zeroed only afterwards
7	 * (terminal-owner rule). Zeroing it in the unseal try/finally made every
8	 * depth-2+ descendant unseal against an all-zero key and misclassified the
9	 * whole sub-subtree as unreadable (false D-12 warnings).
10	 *
11	 * The @cipherbox/core mock below enforces the key-liveness contract the real
12	 * AEAD provides: unsealing with an all-zero parent key throws.
13	 */
14	import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
15	import { CipherBoxClient } from '../client';
16	import { createTestConfig, setupFolder } from './helpers';
17	
18	vi.mock('@cipherbox/crypto', () => ({
19	  clearBytes: vi.fn((arr: Uint8Array) => arr.fill(0)),
20	  unwrapKey: vi.fn().mockResolvedValue(new Uint8Array(64).fill(0x55)),
21	  hexToBytes: vi.fn((hex: string) => new Uint8Array(hex.length / 2)),
22	}));
23	
24	vi.mock('@cipherbox/sdk-core', async (importOriginal) => {
25	  const actual = await importOriginal<typeof import('@cipherbox/sdk-core')>();
26	  return {
27	    ...actual,
28	    loadFolderMetadata: vi.fn(),
29	    updateFolderMetadataAndPublish: vi.fn(),
30	    renameInFolder: vi.fn(),
31	    deleteFromFolder: vi.fn(),
32	    moveItem: vi.fn(),
33	    resolveIpnsRecord: vi.fn(),
34	    fetchFromIpfs: vi.fn(),
35	    rotateReadFromNode: vi.fn(),
36	  };
37	});
38	
39	vi.mock('@cipherbox/core', async (importOriginal) => {
40	  const actual = await importOriginal<typeof import('@cipherbox/core')>();
41	  return {
42	    ...actual,
43	    sealChildReadKey: vi.fn().mockResolvedValue('resealed-dest-hex'),
44	    unsealChildReadKey: vi.fn(async (readKeySealed: string, parentReadKey: Uint8Array) => {
45	      if (parentReadKey.every((b) => b === 0)) {
46	        throw new Error('AEAD failure: unseal attempted with a zeroed parent readKey');
47	      }
48	      if (readKeySealed === 'sealed-broken') {
49	        throw new Error('AEAD failure: corrupt sealed blob');
50	      }
51	      return new Uint8Array(32).fill(0x42);
52	    }),
