71	import * as sdkCore from '@cipherbox/sdk-core';
72	import { unsealNode } from '@cipherbox/core';
73	
74	const SRC_IPNS = 'src-ipns';
75	const DEST_IPNS = 'dest-ipns';
76	const MOVED_IPNS = 'k51moved';
77	const DEPTH1_IPNS = 'k51depth1';
78	const DEPTH2_IPNS = 'k51depth2';
79	
80	/**
81	 * Wire a moved-FOLDER subtree: moved folder → depth-1 subfolder → depth-2 file.
82	 * `depth2Sealed` lets the control test hand the grandchild a corrupt blob.
83	 */
84	function setupMovedFolderTree(depth2Sealed = 'sealed-g') {
85	  vi.mocked(sdkCore.moveItem).mockReturnValue({
86	    updatedSource: [],
87	    updatedDest: [
88	      {
89	        name: 'moved-folder',
90	        ipnsName: MOVED_IPNS,
91	        generation: 0,
92	        versionFloor: 0n,
93	        readKeySealed: 'sealed-moved',
94	      },
95	    ],
96	    movedRef: {
97	      name: 'moved-folder',
98	      ipnsName: MOVED_IPNS,
99	      generation: 0,
100	      versionFloor: 0n,
101	      readKeySealed: 'sealed-moved',
102	    },
103	  });
104	
105	  vi.mocked(sdkCore.resolveIpnsRecord).mockImplementation(async (ipnsName: string) => ({
106	    cid: `cid-${ipnsName}`,
107	    sequenceNumber: 1n,
108	    signatureVerified: true,
109	  }));
110	
111	  const publishedById: Record<string, { id: string; kind: string }> = {
112	    [`cid-${MOVED_IPNS}`]: { id: 'moved-id', kind: 'folder' },
113	    [`cid-${DEPTH1_IPNS}`]: { id: 'depth1-id', kind: 'folder' },
114	    [`cid-${DEPTH2_IPNS}`]: { id: 'depth2-id', kind: 'file' },
115	  };
116	  vi.mocked(sdkCore.fetchFromIpfs).mockImplementation(async (_ctx, cid: string) => {
117	    const published = publishedById[cid];
118	    if (!published) throw new Error(`unexpected cid ${cid}`);
119	    return new TextEncoder().encode(JSON.stringify(published));
120	  });
121	
122	  const childrenById: Record<string, unknown[]> = {
123	    'moved-id': [
124	      {
125	        name: 'depth1',
126	        ipnsName: DEPTH1_IPNS,
127	        generation: 0,
128	        versionFloor: 0n,
129	        readKeySealed: 'sealed-c1',
130	      },
131	    ],
132	    'depth1-id': [
133	      {
134	        name: 'depth2',
135	        ipnsName: DEPTH2_IPNS,
136	        generation: 0,
137	        versionFloor: 0n,
138	        readKeySealed: depth2Sealed,
139	      },
140	    ],
141	    'depth2-id': [],
142	  };
143	  vi.mocked(unsealNode).mockImplementation(
144	    async (published: { id: string }) => ({ children: childrenById[published.id] ?? [] }) as never
145	  );
146	
147	  vi.mocked(sdkCore.updateFolderMetadataAndPublish).mockResolvedValue({
148	    cid: 'bafynew',
149	    newSequenceNumber: 2n,
150	    publishedChildren: [],
151	  });
152	}
153	
154	describe('moveItem — D-12 descendant enumeration walks past depth 1', () => {
155	  let warnSpy: ReturnType<typeof vi.spyOn>;
156	
157	  beforeEach(() => {
158	    vi.clearAllMocks();
159	    warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
160	  });
161	
162	  afterEach(() => {
163	    warnSpy.mockRestore();
164	  });
165	
166	  it('unseals depth-2 descendants with the still-live depth-1 key (no false D-12 unreadable)', async () => {
167	    const client = new CipherBoxClient(createTestConfig());
168	    setupFolder(client, SRC_IPNS);
169	    setupFolder(client, DEST_IPNS);
170	    setupMovedFolderTree();
171	
172	    await client.moveItem(SRC_IPNS, DEST_IPNS, 'file1');
173	
174	    // The walk is fire-and-forget; wait until it has dequeued the depth-2 node.
175	    await vi.waitFor(() => {
176	      const unsealedIds = vi.mocked(unsealNode).mock.calls.map(([p]) => (p as { id: string }).id);
177	      expect(unsealedIds).toContain('depth2-id');
178	    });
179	
180	    const d12Warnings = warnSpy.mock.calls.filter((call) =>
181	      String(call[0]).includes('could not be read after move')
182	    );
183	    expect(d12Warnings).toEqual([]);
184	  });
185	
186	  it('still reports a genuinely unreadable descendant via the D-12 warning (control)', async () => {
187	    const client = new CipherBoxClient(createTestConfig());
188	    setupFolder(client, SRC_IPNS);
189	    setupFolder(client, DEST_IPNS);
190	    setupMovedFolderTree('sealed-broken');
191	
192	    await client.moveItem(SRC_IPNS, DEST_IPNS, 'file1');
193	
194	    await vi.waitFor(() => {
195	      const d12Warnings = warnSpy.mock.calls.filter((call) =>
196	        String(call[0]).includes('could not be read after move')
197	      );
198	      expect(d12Warnings).toHaveLength(1);
199	      expect(d12Warnings[0]?.[1]).toEqual([DEPTH2_IPNS]);
200	    });
201	  });
202	});

